          const d = ev.data || {};
          if (d.note) { try { console.warn('[bloom] Learn voice: ' + d.note); } catch (e) {} return; }
          if (d.backend) { try { console.warn('[bloom] Learn voice backend: ' + d.backend); } catch (e) {} return; }
