        const overlay = document.createElement('div'); overlay.className = 'modal-overlay';
        const modal = document.createElement('div'); modal.className = 'step-div-modal amb-learn-pick';
        const esc = (t) => String(t == null ? '' : t).replace(/[<>&"]/g, '');
