                      const _row = _imp
                        ? _ambEuclidVoicePat(_pu, Math.max(0, L.rotate | 0), steps, 1, 0, _ambImprovSalt(L, _cyc))
                        : null;
                      // WHAT SOUNDED, not what was generated. _row is the improvised
