      try { _ambUpdatePlayheads(E); } catch (e) {}
      try { _ambEuclidStepPlayheads(E); } catch (e) {}
      try { _ambProgOverviewPlayhead(E); } catch (e) {}
      try { _ambSaltReadoutSync(E); } catch (e) {}
