      if (!res || !(res.max > res.min)) return null;
      const name = _ambRampTargetName(cfg, ts[0]);
      const unit = /\.bpm$/i.test(ts[0]) ? 'BPM' : (/\(ms\)|ms$/i.test(name) ? 'ms' : '');
