          if (['pitch','velocity','gate'].indexOf(R.seqSource) < 0) R.seqSource = 'velocity';
          if (['step','smooth'].indexOf(R.seqInterp) < 0) R.seqInterp = 'step';
          if (['zero','hold'].indexOf(R.seqRest) < 0) R.seqRest = 'zero';
